ALTER TABLE public.ecommerce_orders ADD COLUMN checkout_key uuid UNIQUE, ADD COLUMN checkout_hash text;
ALTER TABLE public.ecommerce_customers ADD COLUMN partner_id uuid REFERENCES public.partners(id);
CREATE SEQUENCE public.erp_shop_number_seq;
CREATE FUNCTION public.erp_shop_catalog(p_search text DEFAULT '') RETURNS TABLE(id uuid,code varchar,name varchar,description text,selling_price numeric,vat_rate_id uuid,vat_rate numeric) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT i.id,i.code,i.name,i.description,public.erp_effective_price(i.id,(m.settings->>'location_id')::uuid),i.vat_rate_id,v.rate FROM public.items i JOIN public.vat_rates v ON v.id=i.vat_rate_id AND v.active IS TRUE CROSS JOIN public.module_settings m WHERE m.module_name='webshop' AND m.enabled IS TRUE AND i.active IS TRUE AND (p_search='' OR i.name ILIKE '%'||p_search||'%') ORDER BY i.name LIMIT 100 $$;
REVOKE ALL ON FUNCTION public.erp_shop_catalog(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.erp_shop_catalog(text) TO anon,authenticated;
CREATE FUNCTION public.erp_checkout(p_key uuid,p_request jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE m public.module_settings%ROWTYPE; loc uuid; c public.ecommerce_customers%ROWTYPE; o public.ecommerce_orders%ROWTYPE; line jsonb; item public.items%ROWTYPE; price numeric; rate numeric; net numeric:=0; tax numeric:=0; gross numeric; q numeric; line_net numeric; line_tax numeric; payload jsonb:='[]'; oid uuid; pid uuid; email text; uname text; number text; hash text; BEGIN
 IF p_key IS NULL OR jsonb_typeof(p_request->'lines')<>'array' OR jsonb_array_length(p_request->'lines') NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'Invalid checkout'; END IF;
 hash:=md5(p_request::text); PERFORM pg_advisory_xact_lock(hashtext(p_key::text));
 SELECT * INTO o FROM public.ecommerce_orders WHERE checkout_key=p_key;
 IF FOUND THEN IF o.checkout_hash<>hash THEN RAISE EXCEPTION 'Checkout key used for different request'; END IF; RETURN jsonb_build_object('id',o.id,'order_number',o.order_number,'total',o.total); END IF;
 SELECT * INTO STRICT m FROM public.module_settings WHERE module_name='webshop';
 IF NOT m.enabled THEN RAISE EXCEPTION 'Web shop nije aktivan'; END IF;
 loc:=(m.settings->>'location_id')::uuid;
 IF NOT EXISTS(SELECT 1 FROM public.locations WHERE id=loc AND active IS TRUE AND company_id IS NOT NULL) THEN RAISE EXCEPTION 'Postavite lokaciju web shopa'; END IF;
 IF p_request->>'payment_method'<>'cod' OR NOT coalesce((m.settings->>'pay_cod')::boolean,false) THEN RAISE EXCEPTION 'Odabrano plaćanje nije dostupno'; END IF;
 IF coalesce((m.settings->>'shipping_flat')::numeric,0)<>0 THEN RAISE EXCEPTION 'Obračun dostave zahtijeva konfiguriranu stopu PDV-a; kupnja je zaustavljena bez netočnog iznosa'; END IF;
 IF coalesce(p_request->>'discount_code','')<>'' THEN RAISE EXCEPTION 'Kupon nije konfiguriran'; END IF;
 email:=lower(btrim(p_request->>'customer_email')); uname:=btrim(p_request->>'customer_name');
 IF email IS NULL OR email !~ '^[^@ ]+@[^@ ]+\.[^@ ]+$' OR length(uname) NOT BETWEEN 1 AND 255 THEN RAISE EXCEPTION 'Unesite valjano ime i email'; END IF;
 PERFORM pg_advisory_xact_lock(hashtext(email));
 IF auth.uid() IS NOT NULL THEN SELECT * INTO c FROM public.ecommerce_customers WHERE user_id=auth.uid() FOR UPDATE; END IF;
 IF c.id IS NULL THEN SELECT * INTO c FROM public.ecommerce_customers WHERE lower(email)=email FOR UPDATE; END IF;
 IF c.id IS NOT NULL AND c.status<>'active' THEN RAISE EXCEPTION 'Kupac je blokiran'; END IF;
 IF c.id IS NULL THEN INSERT INTO public.ecommerce_customers(user_id,email,first_name,status) VALUES(auth.uid(),email,uname,'active') RETURNING * INTO c; END IF;
 IF c.partner_id IS NULL THEN INSERT INTO public.partners(code,name,type,email) VALUES('WEB-'||replace(c.id::text,'-',''),uname,'customer',email) RETURNING id INTO pid; UPDATE public.ecommerce_customers SET partner_id=pid WHERE id=c.id; ELSE pid:=c.partner_id; END IF;
 FOR line IN SELECT jsonb_build_object('item_id',x->>'item_id','quantity',sum((x->>'quantity')::numeric)) FROM jsonb_array_elements(p_request->'lines') x GROUP BY x->>'item_id' LOOP
  q:=(line->>'quantity')::numeric; IF q<=0 OR q>10000 THEN RAISE EXCEPTION 'Invalid quantity'; END IF;
  SELECT * INTO STRICT item FROM public.items WHERE id=(line->>'item_id')::uuid AND active IS TRUE;
  SELECT v.rate INTO STRICT rate FROM public.vat_rates v WHERE v.id=item.vat_rate_id AND v.active IS TRUE;
  price:=public.erp_effective_price(item.id,loc); IF price IS NULL OR price<0 THEN RAISE EXCEPTION 'Missing selling price'; END IF;
  line_net:=round(q*price,2); line_tax:=round(line_net*rate/100,2); net:=net+line_net; tax:=tax+line_tax;
  payload:=payload||jsonb_build_array(jsonb_build_object('item_id',item.id,'description',item.name,'quantity',q,'unit_price',price,'vat_rate_id',item.vat_rate_id,'vat_amount',line_tax,'total',line_net+line_tax));
 END LOOP;
 number:='EC-'||to_char(current_date,'YYYY')||'-'||nextval('public.erp_shop_number_seq');
 INSERT INTO public.ecommerce_orders(order_number,customer_id,partner_id,location_id,customer_name,customer_email,customer_phone,shipping_address,shipping_city,shipping_postal_code,shipping_country,payment_method,payment_status,status,subtotal,vat_amount,total,checkout_key,checkout_hash) VALUES(number,c.id,pid,loc,uname,email,p_request->>'customer_phone',p_request->>'shipping_address',p_request->>'shipping_city',p_request->>'shipping_postal_code','BA','cod','pending','new',net,tax,net+tax,p_key,hash) RETURNING id INTO oid;
 INSERT INTO public.ecommerce_order_items(order_id,item_id,description,quantity,unit_price,vat_rate_id,vat_amount,total) SELECT oid,(x->>'item_id')::uuid,x->>'description',(x->>'quantity')::numeric,(x->>'unit_price')::numeric,(x->>'vat_rate_id')::uuid,(x->>'vat_amount')::numeric,(x->>'total')::numeric FROM jsonb_array_elements(payload) x;
 RETURN jsonb_build_object('id',oid,'order_number',number,'subtotal',net,'vat_amount',tax,'total',net+tax);
END $$;
REVOKE ALL ON FUNCTION public.erp_checkout(uuid,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.erp_checkout(uuid,jsonb) TO authenticated;
CREATE FUNCTION public.erp_customer_provision() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE e text; c public.ecommerce_customers%ROWTYPE; BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Confirm your email and sign in'; END IF;
 SELECT email INTO e FROM auth.users WHERE id=auth.uid() AND email_confirmed_at IS NOT NULL;
 IF e IS NULL THEN RAISE EXCEPTION 'Confirm your email'; END IF;
 SELECT * INTO c FROM public.ecommerce_customers WHERE user_id=auth.uid(); IF FOUND THEN RETURN to_jsonb(c); END IF;
 PERFORM pg_advisory_xact_lock(hashtext(lower(e)));
 SELECT * INTO c FROM public.ecommerce_customers WHERE lower(email)=lower(e) FOR UPDATE;
 IF FOUND THEN IF c.user_id IS NOT NULL AND c.user_id<>auth.uid() THEN RAISE EXCEPTION 'Customer ownership conflict'; END IF; UPDATE public.ecommerce_customers SET user_id=auth.uid() WHERE id=c.id RETURNING * INTO c;
 ELSE INSERT INTO public.ecommerce_customers(user_id,email,status) VALUES(auth.uid(),lower(e),'active') RETURNING * INTO c; END IF;
 RETURN to_jsonb(c);
END $$;
REVOKE ALL ON FUNCTION public.erp_customer_provision() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.erp_customer_provision() TO authenticated;